      );
      if (this.session.sheet() !== sheet) return;
      this.sharePcts.update((m) => {
        const next = new Map(m);
        next.delete(c.id);
        return next;
      });
      this.saved.emit(claim);
    } catch (e) {
      if (this.session.sheet() !== sheet) return;
